char*transpose(const char*t){size_t rows=1,max=0,len=0;for(const char*p=t;;p++){if(!*p||*p=='\n'){if(len>max)max=len;len=0;if(!*p)break;rows++;}else len++;}const char**starts=(const char**)malloc(rows*sizeof(char*));size_t*l=(size_t*)malloc(rows*sizeof(size_t));const char*p=t;for(size_t r=0;r<rows;r++){starts[r]=p;l[r]=strcspn(p,"\n");p+=l[r]+(p[l[r]]=='\n');}char*out=(char*)malloc((max*(rows+1)+1)),*q=out;for(size_t c=0;c<max;c++){size_t last=rows;while(last&&l[last-1]<=c)last--;for(size_t r=0;r<last;r++)*q++=c<l[r]?starts[r][c]:' ';if(c+1<max)*q++='\n';}*q=0;free(starts);free(l);return out;}
